import{c as e,Q as l,j as i,m as t}from"./chunks/framework.DK3sgdKX.js";const u=JSON.parse('{"title":"PySTG 编辑器产品愿景（持续讨论稿）","description":"","frontmatter":{},"headers":[],"relativePath":"EDITOR_PRODUCT_VISION.md","filePath":"EDITOR_PRODUCT_VISION.md","lastUpdated":1786282461000}'),n={name:"EDITOR_PRODUCT_VISION.md"};function s(p,a,o,d,c,r){return l(),i("div",null,[...a[0]||(a[0]=[t(`<h1 id="pystg-编辑器产品愿景-持续讨论稿" tabindex="-1">PySTG 编辑器产品愿景（持续讨论稿） <a class="header-anchor" href="#pystg-编辑器产品愿景-持续讨论稿" aria-label="Permalink to &quot;PySTG 编辑器产品愿景（持续讨论稿）&quot;">​</a></h1><blockquote><p>状态：Living Draft / 持续讨论稿</p><p>首版日期：2026-08-09</p><p>当前修订：v0.3（2026-08-09）</p><p>目的：固定我们对“预想中的 PySTG 编辑器”的当前共识，并在后续讨论中持续修订。</p></blockquote><h2 id="_1-文档定位" tabindex="-1">1. 文档定位 <a class="header-anchor" href="#_1-文档定位" aria-label="Permalink to &quot;1. 文档定位&quot;">​</a></h2><p>本文描述 PySTG 编辑器希望最终提供的产品体验、作者工作流和概念边界。</p><p>它回答的是：</p><ul><li>不同经验层级的作者怎样完成一段弹幕、一场 Boss 战和一整关；</li><li>状态图、时间线、行为图、预设和脚本分别解决什么问题；</li><li>内容、行为、工具怎样共享生命周期、类型系统和调试器；</li><li>Safe API、Runtime API、Engine API 怎样形成真正的能力边界；</li><li>编辑器怎样通过渐进式展开服务新人和高级开发者。</li></ul><p>本文不是：</p><ul><li>当前功能清单；</li><li>实施顺序或里程碑承诺；</li><li>schema、ABI 或插件 API 的冻结规范；</li><li>当前版本验收结论；</li><li>对已有路线图完成记录的替代。</li></ul><p>实施顺序、依赖关系和验收证据仍以 <a href="./EDITOR_IMPLEMENTATION_TODO">EDITOR_IMPLEMENTATION_TODO.md</a> 为准；不可破坏的工程边界仍以 <a href="./EDITOR_ARCHITECTURE">EDITOR_ARCHITECTURE.md</a> 为准。本文中的未来概念只有在进入路线图、形成测试契约并通过相应验收后，才能被称为已交付能力。</p><h2 id="_2-一句话愿景" tabindex="-1">2. 一句话愿景 <a class="header-anchor" href="#_2-一句话愿景" aria-label="Permalink to &quot;2. 一句话愿景&quot;">​</a></h2><p>PySTG 应成为一套面向 STG 创作的渐进式 authoring platform：</p><blockquote><p>新人从关卡骨架、时间线和可调预设开始，不写 Python 也能完成结构完整的道中与关底；高级作者可以逐级进入曲线、表达式、行为图和脚本；玩法与工具开发者可以添加新的可视化行为、调试信息和编辑器工具，而不要求普通项目直接接触引擎内部。</p></blockquote><p>产品模型可以概括为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>关卡与阶段大纲</span></span>
<span class="line"><span>    + 时间线编排</span></span>
<span class="line"><span>    + 配方优先的弹幕创作</span></span>
<span class="line"><span>    + 可组合、可查看内部结构的预设</span></span>
<span class="line"><span>    + 类型化变量、事件与激活规则</span></span>
<span class="line"><span>    + 同一资源上的曲线 / 行为图 / 脚本扩展</span></span>
<span class="line"><span>    + 正式运行时预览与分层调试</span></span>
<span class="line"><span>    + Runtime 插件和编辑器工具扩展</span></span></code></pre></div><h2 id="_3-产品成功标准" tabindex="-1">3. 产品成功标准 <a class="header-anchor" href="#_3-产品成功标准" aria-label="Permalink to &quot;3. 产品成功标准&quot;">​</a></h2><h3 id="_3-1-对新人" tabindex="-1">3.1 对新人 <a class="header-anchor" href="#_3-1-对新人" aria-label="Permalink to &quot;3.1 对新人&quot;">​</a></h3><p>一个第一次接触 PySTG 的作者应当能够：</p><ol><li>从完整关卡、道中、Boss 战或单张符卡模板创建内容；</li><li>用阶段卡片组织关卡结构；</li><li>用时间线安排敌人波次、Boss 移动、弹幕、背景、音频和演出；</li><li>用预设和 Inspector 调整弹量、速度、间隔、颜色、路径和难度；</li><li>分别预览 Pattern、波次、阶段和完整关卡；</li><li>保存、关闭、重新打开并继续编辑；</li><li>在不打开行为图、不编写 Python 的情况下完成第一整关。</li></ol><h3 id="_3-2-对进阶内容作者" tabindex="-1">3.2 对进阶内容作者 <a class="header-anchor" href="#_3-2-对进阶内容作者" aria-label="Permalink to &quot;3.2 对进阶内容作者&quot;">​</a></h3><p>进阶作者应当能够在不推倒已有资源的前提下：</p><ul><li>把固定参数改成曲线、变量或受限表达式；</li><li>查看预设的内部组成；</li><li>局部替换某个行为；</li><li>将配方展开为类型化行为图；</li><li>封装自己的项目预设；</li><li>使用统一的事件、取消、预览和调试能力。</li></ul><h3 id="_3-3-对高级开发者" tabindex="-1">3.3 对高级开发者 <a class="header-anchor" href="#_3-3-对高级开发者" aria-label="Permalink to &quot;3.3 对高级开发者&quot;">​</a></h3><p>高级开发者应当能够：</p><ul><li>添加新的行为类型、弹道、组件、碰撞能力或道具机制；</li><li>为自定义行为提供 Inspector、画布控制柄、时间线片段和预览器；</li><li>添加受约束的 Renderer Pass；</li><li>添加资源类型、编译器贡献和外部事件适配器；</li><li>让普通作者通过预设和参数使用这些能力，而不必理解其实现。</li></ul><h3 id="_3-4-反向成功标准" tabindex="-1">3.4 反向成功标准 <a class="header-anchor" href="#_3-4-反向成功标准" aria-label="Permalink to &quot;3.4 反向成功标准&quot;">​</a></h3><p>以下现象说明产品设计失败：</p><ul><li>新人必须先理解一张空白蓝图才能做出第一段弹幕；</li><li>普通常见弹幕需要几十或上百个节点；</li><li>稍复杂的需求只能放弃可视化资源并重写成脚本；</li><li>时间线、行为图和脚本拥有互不兼容的生命周期或调试器；</li><li>模板只会复制一坨不可维护的数据；</li><li>编辑器预览与正式游戏运行时走不同的行为路径；</li><li>为了扩展能力而把高密度子弹展开成节点或逐弹 Python 回调。</li></ul><h2 id="_4-目标用户与默认工作面" tabindex="-1">4. 目标用户与默认工作面 <a class="header-anchor" href="#_4-目标用户与默认工作面" aria-label="Permalink to &quot;4. 目标用户与默认工作面&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用户角色</th><th>主要任务</th><th>默认工作面</th><th>不应默认暴露</th></tr></thead><tbody><tr><td>顶层内容作者</td><td>道中、Boss 阶段、弹幕参数、演出与难度</td><td>阶段大纲、时间线、预设、Inspector、正式预览</td><td>引擎对象、渲染后端、底层池、插件注册</td></tr><tr><td>进阶内容作者</td><td>自定义局部结构、变量关系、事件响应</td><td>配方、曲线、表达式、行为图、调试器</td><td>调度器内部、逐弹回调、裸渲染状态</td></tr><tr><td>玩法开发者</td><td>新组件、新行为、新机制、新弹道</td><td>Runtime API、行为 SDK、插件清单、性能工具</td><td>随意修改调度器和后端内部</td></tr><tr><td>工具开发者</td><td>Inspector、控制柄、轨道、预览器、导入器</td><td>Tool 插件 API、注册表、命令系统</td><td>绕过文档和 Undo/Redo 的直接修改</td></tr><tr><td>引擎开发者</td><td>调度器、渲染后端、资源系统、编译器核心</td><td>Engine API 和仓库内部模块</td><td>面向普通项目的稳定兼容承诺</td></tr></tbody></table><p>“顶层内容作者”不是能力不足的作者，而是选择只处理作品结构与表现、不开发新引擎语义的人。产品不应通过迫使他写脚本来弥补常用创作能力的缺失。</p><h2 id="_5-两条正交的架构轴" tabindex="-1">5. 两条正交的架构轴 <a class="header-anchor" href="#_5-两条正交的架构轴" aria-label="Permalink to &quot;5. 两条正交的架构轴&quot;">​</a></h2><p>最终设计包含两条互相独立的轴。</p><h3 id="_5-1-产品职责轴-内容、行为、工具" tabindex="-1">5.1 产品职责轴：内容、行为、工具 <a class="header-anchor" href="#_5-1-产品职责轴-内容、行为、工具" aria-label="Permalink to &quot;5.1 产品职责轴：内容、行为、工具&quot;">​</a></h3><h4 id="内容-content" tabindex="-1">内容（Content） <a class="header-anchor" href="#内容-content" aria-label="Permalink to &quot;内容（Content）&quot;">​</a></h4><p>内容由版本化数据和标准组件构成，可以通过阶段大纲、场景画布、时间线、配方和领域图编辑。</p><p>内容描述“作品是什么”，例如：</p><ul><li>一关有哪些阶段；</li><li>某个阶段有哪些敌人波次；</li><li>某张符卡引用哪个 Pattern；</li><li>背景在什么时候过渡；</li><li>某个参数绑定哪个变量。</li></ul><h4 id="行为-behavior" tabindex="-1">行为（Behavior） <a class="header-anchor" href="#行为-behavior" aria-label="Permalink to &quot;行为（Behavior）&quot;">​</a></h4><p>行为描述“某个效果怎样运行”，由数据化动作、协程式动作、编译后的批量运行数据和脚本扩展构成。</p><p>所有行为应共享：</p><ul><li>类型化输入和输出；</li><li><code>start / update / event / stop / cancel</code> 生命周期；</li><li>所有权和取消传播；</li><li>变量、事件和资源引用协议；</li><li>正式预览和调试协议；</li><li>结构化错误和性能统计。</li></ul><h4 id="工具-tool" tabindex="-1">工具（Tool） <a class="header-anchor" href="#工具-tool" aria-label="Permalink to &quot;工具（Tool）&quot;">​</a></h4><p>工具由编辑器插件构成，为内容和行为提供：</p><ul><li>Inspector 编辑器；</li><li>画布控制柄；</li><li>专用预览器；</li><li>时间线轨道和片段；</li><li>搜索项和创建命令；</li><li>导入器、验证器和诊断视图。</li></ul><p>工具只能通过文档命令和注册协议修改作者资源，不能绕过 Undo/Redo 直接改内部状态。</p><h3 id="_5-2-信任轴-safe-api、runtime-api、engine-api" tabindex="-1">5.2 信任轴：Safe API、Runtime API、Engine API <a class="header-anchor" href="#_5-2-信任轴-safe-api、runtime-api、engine-api" aria-label="Permalink to &quot;5.2 信任轴：Safe API、Runtime API、Engine API&quot;">​</a></h3><p>职责轴和信任轴不能混成一条继承链。一个自定义行为可以属于 Runtime 权限，同时由 Tool 插件提供编辑器控制柄，并以 Content 资源实例出现在普通作者的项目里。</p><h4 id="safe-api-内容创作者" tabindex="-1">Safe API：内容创作者 <a class="header-anchor" href="#safe-api-内容创作者" aria-label="Permalink to &quot;Safe API：内容创作者&quot;">​</a></h4><p>Safe API 只提供经过授权、可验证、可取消的能力：</p><ul><li>批量发射 Pattern 或子弹；</li><li>移动自己拥有或被显式授予的对象句柄；</li><li>播放已注册的 <code>res://</code> 资源；</li><li>读取只读游戏状态快照；</li><li>等待类型化事件；</li><li>设置类型化局部变量；</li><li>发出受 schema 约束的事件；</li><li>创建受配额限制的稀疏行为实例。</li></ul><p>Safe API 不返回 Player、Pool、Renderer、Manager 等引擎活对象，不允许任意文件、网络、进程和模块访问。</p><h4 id="runtime-api-玩法开发者" tabindex="-1">Runtime API：玩法开发者 <a class="header-anchor" href="#runtime-api-玩法开发者" aria-label="Permalink to &quot;Runtime API：玩法开发者&quot;">​</a></h4><p>Runtime API 面向受信任项目代码，可以：</p><ul><li>创建自定义稀疏组件；</li><li>注册事件和行为；</li><li>定义新弹道或批量运动内核；</li><li>查询碰撞系统或注册碰撞组件；</li><li>创建自定义道具与机制；</li><li>注册受约束的 Renderer Pass；</li><li>为自定义行为提供编译器和调试快照。</li></ul><p>Runtime 扩展可以是进程内 Python，但必须明确标记为受信任代码，并遵守版本化 SDK、资源所有权、线程和清理约定。</p><h4 id="engine-api-引擎开发者" tabindex="-1">Engine API：引擎开发者 <a class="header-anchor" href="#engine-api-引擎开发者" aria-label="Permalink to &quot;Engine API：引擎开发者&quot;">​</a></h4><p>Engine API 允许：</p><ul><li>修改调度器；</li><li>修改渲染后端和渲染图；</li><li>修改资源生命周期；</li><li>添加底层资源类型；</li><li>定义编辑器核心插件点；</li><li>增加或修改编译器节点和运行时 IR。</li></ul><p>Engine API 是内部接口，可以随引擎版本迁移；普通项目不应直接依赖它。</p><h4 id="关于-python-沙箱" tabindex="-1">关于 Python 沙箱 <a class="header-anchor" href="#关于-python-沙箱" aria-label="Permalink to &quot;关于 Python 沙箱&quot;">​</a></h4><p>仅仅给 Python 脚本一个较小的 <code>ctx</code> 对象，不能构成安全沙箱。任意进程内 Python 仍可能导入模块、访问文件或接触内部对象。</p><p>因此未来的 Safe 行为应优先采用：</p><ul><li>数据化动作；</li><li>白名单表达式；</li><li>状态图和可暂停行为计划；</li><li>经过验证的行为字节码或 DSL。</li></ul><p>如果 Safe 层必须运行任意 Python，原则上应使用独立进程和能力代理；进程内 Python 默认属于受信任的 Runtime 层。</p><h2 id="_6-作者看到的核心层级" tabindex="-1">6. 作者看到的核心层级 <a class="header-anchor" href="#_6-作者看到的核心层级" aria-label="Permalink to &quot;6. 作者看到的核心层级&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Project</span></span>
<span class="line"><span>└─ SceneDocument（保存、Undo/Redo 与编译边界）</span></span>
<span class="line"><span>   └─ Stage / Boss / Spell（语义所有者）</span></span>
<span class="line"><span>      └─ StateGraphSpec（分层状态结构）</span></span>
<span class="line"><span>         └─ StateSpec / Section</span></span>
<span class="line"><span>            ├─ Local Variables</span></span>
<span class="line"><span>            ├─ Timeline（编排）</span></span>
<span class="line"><span>            │  └─ Clip Definition</span></span>
<span class="line"><span>            │     └─ Pattern / Behavior / Resource</span></span>
<span class="line"><span>            ├─ Child StateGraph（可选）</span></span>
<span class="line"><span>            └─ Transitions（条件与事件）</span></span></code></pre></div><p><code>StageFlow</code> 和 <code>PhaseFlow</code> 只是在不同语义所有者下显示同一种 <code>StateGraphSpec</code> 的编辑器名称，不做成两种互不兼容的资源或运行时。<code>ActivationSpec</code> 等字段名仍是概念名，最终 schema 需要另行版本化。</p><h3 id="_6-1-状态图负责-现在处于哪个阶段" tabindex="-1">6.1 状态图负责“现在处于哪个阶段” <a class="header-anchor" href="#_6-1-状态图负责-现在处于哪个阶段" aria-label="Permalink to &quot;6.1 状态图负责“现在处于哪个阶段”&quot;">​</a></h3><p>状态图适合表达：</p><ul><li>Intro、Normal、Spell、Enrage、End；</li><li>Boss 血量达到阈值后切换阶段；</li><li>收到完成事件后转移；</li><li>超时、击破、失败或玩家选择产生的分支；</li><li>父状态退出时统一取消其内部行为。</li></ul><p>状态图不负责描述每一发子弹，也不负责表现所有时间关键帧。</p><h3 id="_6-2-时间线负责-这个阶段内部怎样编排" tabindex="-1">6.2 时间线负责“这个阶段内部怎样编排” <a class="header-anchor" href="#_6-2-时间线负责-这个阶段内部怎样编排" aria-label="Permalink to &quot;6.2 时间线负责“这个阶段内部怎样编排”&quot;">​</a></h3><p>时间线适合表达：</p><ul><li>已知顺序、持续时间和重叠关系；</li><li>Boss 移动；</li><li>Pattern、音频、背景、UI 和演出片段；</li><li>参数曲线；</li><li>相对于标记或事件的延迟；</li><li>某个条件满足后实例化一个预先创作的片段。</li></ul><p>时间线不直接进入 Pattern 内部连线，也不修改作者文档来表示运行时重复实例。</p><h3 id="_6-3-行为图负责-一个效果内部怎样运行" tabindex="-1">6.3 行为图负责“一个效果内部怎样运行” <a class="header-anchor" href="#_6-3-行为图负责-一个效果内部怎样运行" aria-label="Permalink to &quot;6.3 行为图负责“一个效果内部怎样运行”&quot;">​</a></h3><p>行为图适合表达：</p><ul><li>发射源、形状、瞄准、调度、运动和修饰器的组合；</li><li>一个效果内部可复用的数据流和稀疏控制流；</li><li>局部条件、事件响应和可替换实现；</li><li>插件提供的高级行为节点。</li></ul><p>行为图不是整个关卡的万能图。UI、背景、状态、时间线和弹幕保留各自的领域视图，只共享文档、类型、命令、变量、事件、预览和调试基础设施。</p><h3 id="_6-4-状态图与-scenedocument-的持久化边界" tabindex="-1">6.4 状态图与 SceneDocument 的持久化边界 <a class="header-anchor" href="#_6-4-状态图与-scenedocument-的持久化边界" aria-label="Permalink to &quot;6.4 状态图与 SceneDocument 的持久化边界&quot;">​</a></h3><p>愿景层固定以下方向：</p><ul><li><code>SceneDocument</code> 继续作为一个 Stage、Boss 战或 Spell 的作者真源、保存边界、Undo/Redo 边界和编译入口；</li><li><code>StateGraphSpec</code> 是 <code>SceneDocument</code> 内的版本化子结构，不另建一份与 Scene 竞争的关卡文档；</li><li><code>StateSpec</code> 是带稳定 UUID 的内嵌子资源，默认不是散落在资源浏览器中的独立文件；</li><li>每个 State 直接拥有自己的局部变量、局部时间线和转移，删除、复制、Undo/Redo 可以形成一个符合作者直觉的事务；</li><li>Composite State 可以拥有子状态图；进入父状态时进入其初始子状态，退出父状态时取消整个子树；</li><li>转移默认只连接同级 State。子图通过声明的完成结果或类型化事件与父级交流，不跨层拉线；</li><li>Pattern、Behavior、UI、Background 和预设继续使用项目相对资源引用，State 只实例化或绑定它们；</li><li>跨项目复用阶段时，保存为 <code>PhasePreset</code>，而不是让另一个 Scene 直接引用本 Scene 内部 State 的 UUID。</li></ul><p>现有 <code>SceneDocument.tracks</code> 在未来迁移到该结构时，应进入一个隐式的默认 State 或父级时间线，并保留 Track、Clip、Keyframe 的稳定 ID。没有实际文件大小、协作或加载性能证据前，不增加独立 <code>FlowDocument</code>、<code>StateDocument</code> 或 <code>SequenceDocument</code> 三套文件类型。以后若确实需要拆分，也应通过显式“提取为资源”完成，而不是改变默认新手流程。</p><h2 id="_7-状态图、时间线和行为图怎样互相影响" tabindex="-1">7. 状态图、时间线和行为图怎样互相影响 <a class="header-anchor" href="#_7-状态图、时间线和行为图怎样互相影响" aria-label="Permalink to &quot;7. 状态图、时间线和行为图怎样互相影响&quot;">​</a></h2><p>三者不直接跨画布拉长线，而通过三个中立协议交互：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>类型化变量（数据）</span></span>
<span class="line"><span>类型化事件（离散信号）</span></span>
<span class="line"><span>激活与停止规则（生命周期）</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>State / Phase</span></span>
<span class="line"><span>    ├─ owns Timeline</span></span>
<span class="line"><span>    ├─ reads Variables</span></span>
<span class="line"><span>    └─ transitions on Conditions / Events</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Timeline</span></span>
<span class="line"><span>    ├─ writes or animates declared Variables</span></span>
<span class="line"><span>    ├─ instantiates Behavior / Pattern resources</span></span>
<span class="line"><span>    └─ emits typed Events</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Behavior Instance</span></span>
<span class="line"><span>    ├─ reads bound inputs and snapshots</span></span>
<span class="line"><span>    ├─ publishes declared outputs / Events</span></span>
<span class="line"><span>    └─ stops when its token or owner is cancelled</span></span></code></pre></div><h3 id="_7-1-类型化变量表" tabindex="-1">7.1 类型化变量表 <a class="header-anchor" href="#_7-1-类型化变量表" aria-label="Permalink to &quot;7.1 类型化变量表&quot;">​</a></h3><p>共享变量必须声明：</p><ul><li>名称和类型；</li><li>默认值；</li><li>作用域：项目、关卡、状态、片段或行为实例；</li><li>谁可以写；</li><li>是否可动画、是否进入回放记录；</li><li>调试显示方式。</li></ul><p>示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>boss.hp_ratio          float    运行时只读</span></span>
<span class="line"><span>phase.enrage           bool     状态级</span></span>
<span class="line"><span>mapping.c              complex  状态级，可被时间线动画</span></span>
<span class="line"><span>difficulty.rank        float    关卡级</span></span>
<span class="line"><span>emitter.generated      int      行为输出，只读</span></span></code></pre></div><p>时间线可以动画变量，行为可以读取绑定，状态图可以用变量判断转移。任何一方都不应通过取得另一方的内部对象来修改状态。</p><p>变量的运行所有权固定为：</p><table tabindex="0"><thead><tr><th>作用域</th><th>生命周期</th><th>典型用途</th></tr></thead><tbody><tr><td>Project Config</td><td>启动时读取，运行期间默认只读</td><td>难度、玩家选项、目标平台配置</td></tr><tr><td>Stage</td><td>进入关卡时创建，跨 State 保留，关卡结束销毁</td><td>rank、累计击破、分支选择</td></tr><tr><td>State</td><td>每次进入 State 创建，退出时销毁</td><td>阶段进度、局部计数、Enrage 标记</td></tr><tr><td>Clip / Reaction</td><td>每个运行实例独立，完成或取消时销毁</td><td>循环序号、触发计数、局部等待状态</td></tr><tr><td>Behavior</td><td>每个行为实例独立</td><td>生成进度、算法内部记忆</td></tr><tr><td>Engine Snapshot</td><td>引擎每帧发布，只读</td><td>HP、位置、碰撞结果、性能计数</td></tr></tbody></table><p>作者文档只保存声明和默认值，不在停止预览时把运行值写回文档。跨局持久化属于 Save/Profile 系统，不伪装成普通内容变量。跨 State 传值必须使用 Stage 作用域变量或显式输出映射，不能依赖上一个 State 已销毁的局部内存。</p><p>写权限遵循“默认单一权威写入者”：</p><ul><li>Engine Snapshot 只能读取；</li><li>时间线只能写声明为 <code>animatable</code> 的变量或属性；</li><li>Safe Action 只能通过声明式 <code>set / add / toggle / reset</code> 命令写入获准目标；</li><li>Behavior 只能发布已声明的输出，不能取得全局字典后任意改值；</li><li>同一帧可能存在多个写入者时，默认产生编译诊断，作者必须显式选择优先级或该类型支持的 reducer/blend；</li><li>变量名、类型或作用域不兼容时，热重载不得猜测迁移。正式预览默认重建并确定性重放到当前帧。</li></ul><h3 id="_7-2-类型化事件" tabindex="-1">7.2 类型化事件 <a class="header-anchor" href="#_7-2-类型化事件" aria-label="Permalink to &quot;7.2 类型化事件&quot;">​</a></h3><p>事件适合表达离散事实：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wave.completed</span></span>
<span class="line"><span>enemy.all_defeated</span></span>
<span class="line"><span>spell.declared</span></span>
<span class="line"><span>spell.started</span></span>
<span class="line"><span>mapping.finished</span></span>
<span class="line"><span>boss.defeated</span></span>
<span class="line"><span>background.transition_finished</span></span></code></pre></div><p>事件需要 schema、来源、帧号和生命周期所有者。外部适配器也必须先规范化为类型化事件，不能从网络线程直接改游戏系统。</p><p>事件只描述“刚才发生了什么”，不携带对消费者的命令。例如对象行为可以发布 <code>decoy.hit</code>，但不应发布 <code>start_timeline_clip(&quot;counter_burst&quot;)</code>。事件生产者不需要知道状态图、时间线或背景系统将如何响应；声明式反应规则负责在它们之间完成匹配。对象与高密度弹幕的生命周期事件和反应模型见第 17 节。</p><h3 id="_7-3-激活规则" tabindex="-1">7.3 激活规则 <a class="header-anchor" href="#_7-3-激活规则" aria-label="Permalink to &quot;7.3 激活规则&quot;">​</a></h3><p>一个时间线片段不应只有固定 <code>start_frame</code>，还应能声明概念上的激活规则：</p><ul><li>固定时间；</li><li>相对父状态进入时间；</li><li>相对某个标记或事件；</li><li>条件从假变真的上升沿；</li><li>条件保持为真期间持续运行；</li><li>手动或事件触发；</li><li>启动时计算一次的动态延迟。</li></ul><p>条件触发不使用含糊的单个布尔开关，而提供明确模式：</p><ul><li><code>on_rise</code>：条件从假变真时启动一次，是新建条件片段的默认值；</li><li><code>while_true</code>：条件为真时保持一个实例运行，变假时停止，不代表每帧重启；</li><li><code>on_fall</code>：条件从真变假时启动一次；</li><li><code>on_change</code>：值发生变化时启动，属于高级选项；</li><li>类型化 Event 天然是离散脉冲，不再额外选择边沿模式。</li></ul><p>默认条件规则是 <code>on_rise + once_per_scope</code>。需要重复命中反击、循环生成或保持运行时，作者必须从可读的策略字段中明确选择，而不是依靠图的连线形状猜测语义。</p><p>对应的停止规则包括：</p><ul><li>固定持续时间；</li><li>条件变假；</li><li>收到事件；</li><li>行为自行完成；</li><li>父状态退出；</li><li>显式取消。</li></ul><h3 id="_7-4-运行时实例策略" tabindex="-1">7.4 运行时实例策略 <a class="header-anchor" href="#_7-4-运行时实例策略" aria-label="Permalink to &quot;7.4 运行时实例策略&quot;">​</a></h3><p>“条件产生一个时间线内容”不意味着运行时改写作者文档。作者保存片段定义；条件满足时，调度器创建运行时实例。</p><p>片段应能声明：</p><ul><li><code>once</code>：只启动一次；</li><li><code>retrigger</code>：每次上升沿重新启动；</li><li><code>restart</code>：新触发替换旧实例；</li><li><code>parallel</code>：允许并行实例；</li><li><code>max_instances</code>：限制并发数；</li><li><code>cooldown</code>：限制重触发频率。</li></ul><p>作者片段 ID 和运行实例 ID 必须分开，调试器需要同时显示二者。</p><p>安全默认值是 <code>once_per_scope</code>、<code>max_instances = 1</code>，活动期间的新触发使用 <code>ignore_while_running</code>。<code>restart</code> 和 <code>parallel</code> 必须由作者或预设显式打开；允许并行时必须同时声明 <code>max_instances</code>。立即完成的无状态批量 Action 可以逐事件处理，但仍受同帧聚合与生成预算约束。</p><h3 id="_7-5-动态时间的确定性" tabindex="-1">7.5 动态时间的确定性 <a class="header-anchor" href="#_7-5-动态时间的确定性" aria-label="Permalink to &quot;7.5 动态时间的确定性&quot;">​</a></h3><p>动态时间必须说明求值时刻：</p><ul><li><code>delay = difficulty * 30</code>：父状态进入或片段被调度时计算一次；</li><li><code>playback_rate &lt;- rank</code>：运行期间按明确边界持续采样；</li><li><code>start_when hp_ratio &lt; 0.5</code>：监听条件上升沿；</li><li>已经发生的开始时间不能因变量改变而追溯移动。</li></ul><p>默认情况下不允许一个表达式每帧重写已经过去的 <code>start_frame</code>，避免时间旅行和不可复现行为。</p><h3 id="_7-6-每帧执行顺序与事件可见性" tabindex="-1">7.6 每帧执行顺序与事件可见性 <a class="header-anchor" href="#_7-6-每帧执行顺序与事件可见性" aria-label="Permalink to &quot;7.6 每帧执行顺序与事件可见性&quot;">​</a></h3><p>愿景层固定“事件不重入、下一固定帧可见”的语义：</p><ol><li>在帧边界收集外部输入和上一帧发布的 Event Outbox，形成本帧只读 Inbox；</li><li>更新正式运行状态与 Engine Snapshot；</li><li>在同一快照上计算状态转移、激活条件和反应匹配；</li><li>先提交状态退出/进入与取消传播，再启动仍然有效的 Clip、Reaction 和 Behavior 实例；</li><li>采样时间线曲线、变量和属性轨道；</li><li>执行稀疏行为、Pattern 和批量运行数据；</li><li>将本帧新事实写入 Event Outbox，记录调试轨迹，供下一固定帧读取。</li></ol><p>事件处理器发布的新事件不能在当前 dispatch 中再次触发处理器。这样一次死亡开花至少跨一个确定的调度边界，不会产生无法终止的同栈事件递归。若同一个事件同时导致状态转移和旧 State 内的反应，状态生命周期优先：退出 State 的新反应不会启动；需要保留的击破演出应写成 Exit Action 或下一 State 的 Entry Timeline。</p><p>外部输入只在帧边界规范化；网络线程不能获得“同帧立即修改游戏”的特殊通道。能静态识别的反应环在编译期报告；动态事件携带因果链信息并受目标运行配置的最大深度约束。</p><h3 id="_7-7-动态实例和冲突的可视化" tabindex="-1">7.7 动态实例和冲突的可视化 <a class="header-anchor" href="#_7-7-动态实例和冲突的可视化" aria-label="Permalink to &quot;7.7 动态实例和冲突的可视化&quot;">​</a></h3><p>时间线始终区分作者定义与运行时实例：</p><ul><li>尚未触发的 <code>ReactiveClip</code> 显示为空心或虚线的武装区间；</li><li>触发后在定义上叠加实际触发帧、原因和实例数量，不创建可保存的新 Clip；</li><li><code>restart</code> 显示旧实例被取消和新实例接管的 trace；</li><li><code>parallel</code> 以堆叠实例行或 <code>×N</code> 徽标显示，选中后展开各自的开始帧、所有者和状态；</li><li>被 <code>cooldown</code>、<code>max_instances</code>、Gate 或预算抑制的触发保留可检查标记，不能无声消失。</li></ul><p>属性和变量冲突按 <code>target + property</code> 分组显示。未来新建内容的默认规则是“重叠写入需要显式解决”，编辑器在轨道重叠处显示条纹和诊断；作者可选择有顺序的 <code>override</code>、数值类型支持的 <code>add / multiply / weighted blend</code>，或调整作用域。现有 Scene 的确定性 last-wins 顺序作为兼容语义保留，但不作为新人新建内容的隐式默认值。</p><h2 id="_8-新人的完整创作流程" tabindex="-1">8. 新人的完整创作流程 <a class="header-anchor" href="#_8-新人的完整创作流程" aria-label="Permalink to &quot;8. 新人的完整创作流程&quot;">​</a></h2><h3 id="_8-1-创建项目或资源" tabindex="-1">8.1 创建项目或资源 <a class="header-anchor" href="#_8-1-创建项目或资源" aria-label="Permalink to &quot;8.1 创建项目或资源&quot;">​</a></h3><p>新建入口首先询问作者想做什么：</p><ul><li>一段道中；</li><li>一张符卡；</li><li>一场 Boss 战；</li><li>一整关；</li><li>一个 Pattern 实验；</li><li>一个背景或 UI 资源。</li></ul><p>编辑器应从可运行骨架创建内容，而不是只提供空场景。</p><h3 id="_8-2-完整关卡模板" tabindex="-1">8.2 完整关卡模板 <a class="header-anchor" href="#_8-2-完整关卡模板" aria-label="Permalink to &quot;8.2 完整关卡模板&quot;">​</a></h3><p>标准关卡骨架可以是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Opening</span></span>
<span class="line"><span>→ Wave A</span></span>
<span class="line"><span>→ Wave B</span></span>
<span class="line"><span>→ Midboss</span></span>
<span class="line"><span>→ Transition</span></span>
<span class="line"><span>→ Wave C</span></span>
<span class="line"><span>→ Boss Entrance</span></span>
<span class="line"><span>→ Boss Battle</span></span>
<span class="line"><span>→ Ending</span></span></code></pre></div><p>作者先删减、重命名、重排阶段并选择默认背景和 BGM，而不是先连接底层节点。</p><h3 id="_8-3-道中开发" tabindex="-1">8.3 道中开发 <a class="header-anchor" href="#_8-3-道中开发" aria-label="Permalink to &quot;8.3 道中开发&quot;">​</a></h3><p>作者点开一个 Wave 阶段后，看到局部时间线：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>敌人波次    [左右妖精编队────────]</span></span>
<span class="line"><span>移动轨道    [入场]        [离场]</span></span>
<span class="line"><span>主要弹幕          [自机狙连射────]</span></span>
<span class="line"><span>背景        [云层加速────────────]</span></span>
<span class="line"><span>音效             [出现音效]</span></span></code></pre></div><p>拖入“左右妖精编队”后，Inspector 暴露：</p><ul><li>敌人资源；</li><li>数量和编队形状；</li><li>入场与离场路径；</li><li>生成间隔；</li><li>攻击预设；</li><li>掉落配置；</li><li>启动与完成条件；</li><li>难度缩放。</li></ul><p>常见关系如“上一波全灭后等待 0.8 秒”应由激活面板完成，不要求打开行为图。</p><h3 id="_8-4-关底与符卡开发" tabindex="-1">8.4 关底与符卡开发 <a class="header-anchor" href="#_8-4-关底与符卡开发" aria-label="Permalink to &quot;8.4 关底与符卡开发&quot;">​</a></h3><p>Boss 模板可以产生：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Entrance</span></span>
<span class="line"><span>→ Nonspell 1</span></span>
<span class="line"><span>→ Spell 1</span></span>
<span class="line"><span>→ Nonspell 2</span></span>
<span class="line"><span>→ Spell 2</span></span>
<span class="line"><span>→ Enrage</span></span>
<span class="line"><span>→ Defeat</span></span></code></pre></div><p>每个阶段先编辑：</p><ul><li>HP、时间限制和奖励；</li><li>符卡名称；</li><li>击破、超时与消弹策略；</li><li>Boss 初始位置；</li><li>背景、BGM 和宣言；</li><li>进入、完成和退出条件。</li></ul><p>阶段内部时间线安排 Boss 移动、符卡宣言、主要弹幕、辅助弹幕、背景和音效。Pattern 先在配方模式编辑子弹、形状、瞄准、间隔、速度、旋转和修饰器；只有局部结构超出配方能力时才展开行为图。</p><h3 id="_8-5-预览阶梯" tabindex="-1">8.5 预览阶梯 <a class="header-anchor" href="#_8-5-预览阶梯" aria-label="Permalink to &quot;8.5 预览阶梯&quot;">​</a></h3><p>作者应能从不同层级启动同一正式运行时：</p><ol><li>Pattern 预览；</li><li>单个时间线片段预览；</li><li>波次或阶段预览；</li><li>Boss 多阶段预览；</li><li>从关卡标记开始；</li><li>完整关卡运行。</li></ol><p>每种预览都应记录初始变量、随机种子、实际触发帧和资源版本，以便复现。</p><p>时间轴拖动和 Stage 级 <code>seek</code> 的正式语义固定为：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>重置预览作用域</span></span>
<span class="line"><span>→ 从作用域入口按固定帧确定性重放</span></span>
<span class="line"><span>→ 到目标帧暂停</span></span>
<span class="line"><span>→ 用正式运行时快照更新编辑器</span></span></code></pre></div><p>它不尝试从目标帧反推出此前的变量、随机数、事件、子弹或 Task 状态，也不要求作者维护另一套快照初始化数据。Pattern 或单片段预览从自身局部入口开始；阶段、Boss 和整关预览若依赖父级状态，就从相应父级入口重放。</p><p>重放期间，内部状态改变、事件和反应必须照常计算；音频播放、网络发送、文件写入等由引擎代理的外部副作用只更新逻辑状态而不实际重复执行，到目标帧后再恢复需要持续存在的 BGM/背景状态。Runtime 插件必须声明 replay policy；绕过能力代理自行产生外部副作用的插件被标记为不可重放。依赖真实外部输入的片段只有在输入已被记录时才能精确重放，否则调试器明确标记“不可复现输入”。</p><p>未来可以用确定性检查点缓存加速，但缓存必须与从头重放逐帧等价，失效时回退到完整重放。它只是透明性能优化，不改变 authoring 语义，也不成为当前短期要解决的结构问题。拖动过程中可以先显示作者曲线和静态姿态；只有收到正式运行时目标帧快照后，界面才能标记为 Runtime Preview。</p><h2 id="_9-什么时候使用哪一种工具" tabindex="-1">9. 什么时候使用哪一种工具 <a class="header-anchor" href="#_9-什么时候使用哪一种工具" aria-label="Permalink to &quot;9. 什么时候使用哪一种工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>作者的问题</th><th>首选工具</th></tr></thead><tbody><tr><td>什么先发生、持续多久、怎样重叠</td><td>时间线</td></tr><tr><td>当前处于哪个阶段、何时转移</td><td>状态图</td></tr><tr><td>一次攻击内部怎样生成和变化</td><td>Pattern 配方或行为图</td></tr><tr><td>参数随时间怎样变化</td><td>曲线或属性轨道</td></tr><tr><td>参数怎样依赖游戏状态</td><td>变量绑定或受限表达式</td></tr><tr><td>等待 HP、事件或上一波完成</td><td>激活条件</td></tr><tr><td>多处复用一组结构</td><td>预设或子行为</td></tr><tr><td>创造引擎还不认识的新算法语义</td><td>Runtime 脚本或行为插件</td></tr><tr><td>创造新渲染阶段、资源或编译器能力</td><td>Runtime / Engine 插件</td></tr></tbody></table><p>时间线功能不足时，不应逼用户用行为图补洞；行为图存在也不意味着所有时间和状态关系都应塞进图里。</p><h2 id="_10-渐进式展开" tabindex="-1">10. 渐进式展开 <a class="header-anchor" href="#_10-渐进式展开" aria-label="Permalink to &quot;10. 渐进式展开&quot;">​</a></h2><p>同一资源应提供以下深度，而不是五套互不兼容的模式：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>L0  预设卡片</span></span>
<span class="line"><span>L1  常用参数</span></span>
<span class="line"><span>L2  高级参数、曲线、变量和表达式</span></span>
<span class="line"><span>L3  内部时间线或行为图</span></span>
<span class="line"><span>L4  局部脚本 / Runtime 扩展源码</span></span>
<span class="line"><span>L5  Engine 内部实现</span></span></code></pre></div><p>用户进入下一层时，不应丢失：</p><ul><li>资源 UUID；</li><li>引用关系；</li><li>Undo/Redo 历史边界；</li><li>正式预览入口；</li><li>诊断定位；</li><li>调试实例身份。</li></ul><p>配方、曲线、行为图和可选 ScriptBehavior 仍是同一个资源的不同深度，不应变成互相漂移的副本。</p><h2 id="_11-预设系统" tabindex="-1">11. 预设系统 <a class="header-anchor" href="#_11-预设系统" aria-label="Permalink to &quot;11. 预设系统&quot;">​</a></h2><p>预设比继续增加节点数量更重要。大部分新人希望“找一个差不多的效果再调整”，而不是从原子节点开始编程。</p><h3 id="_11-1-预设层级" tabindex="-1">11.1 预设层级 <a class="header-anchor" href="#_11-1-预设层级" aria-label="Permalink to &quot;11.1 预设层级&quot;">​</a></h3><h4 id="pattern-预设" tabindex="-1">Pattern 预设 <a class="header-anchor" href="#pattern-预设" aria-label="Permalink to &quot;Pattern 预设&quot;">​</a></h4><ul><li>自机狙；</li><li>奇数弹、偶数弹；</li><li>圆形开花；</li><li>扇形扫射；</li><li>单螺旋、双螺旋、交错螺旋；</li><li>延迟转向、子弹分裂、速度层叠；</li><li>波纹、米弹墙。</li></ul><h4 id="wave-预设" tabindex="-1">Wave 预设 <a class="header-anchor" href="#wave-预设" aria-label="Permalink to &quot;Wave 预设&quot;">​</a></h4><ul><li>左右夹击；</li><li>编队入场；</li><li>环绕入场；</li><li>道中墙；</li><li>精英敌人；</li><li>中 Boss 过渡。</li></ul><h4 id="phase-预设" tabindex="-1">Phase 预设 <a class="header-anchor" href="#phase-预设" aria-label="Permalink to &quot;Phase 预设&quot;">​</a></h4><ul><li>普通攻击阶段；</li><li>标准符卡阶段；</li><li>狂暴阶段；</li><li>耐久或超时阶段；</li><li>击破演出阶段。</li></ul><h4 id="stage-骨架" tabindex="-1">Stage 骨架 <a class="header-anchor" href="#stage-骨架" aria-label="Permalink to &quot;Stage 骨架&quot;">​</a></h4><ul><li>短道中；</li><li>标准完整关卡；</li><li>Boss Rush；</li><li>符卡练习；</li><li>耐久关。</li></ul><h4 id="background-presentation-预设" tabindex="-1">Background / Presentation 预设 <a class="header-anchor" href="#background-presentation-预设" aria-label="Permalink to &quot;Background / Presentation 预设&quot;">​</a></h4><ul><li>道中滚动背景；</li><li>符卡背景过渡；</li><li>雾、扭曲、镜头推进；</li><li>符卡宣言与 UI 演出。</li></ul><h3 id="_11-2-预设的外部接口" tabindex="-1">11.2 预设的外部接口 <a class="header-anchor" href="#_11-2-预设的外部接口" aria-label="Permalink to &quot;11.2 预设的外部接口&quot;">​</a></h3><p>预设不是不可拆的模板。它应声明：</p><ul><li>稳定 ID 和版本；</li><li>参数 schema、单位和默认值；</li><li>资源插槽；</li><li>启动与停止接口；</li><li>输入变量；</li><li>输出变量和事件；</li><li>取消策略；</li><li>内部行为图、时间线片段或资源引用；</li><li>来源、标签、本地化名称和性能等级。</li></ul><h3 id="_11-3-查看、覆盖与展开" tabindex="-1">11.3 查看、覆盖与展开 <a class="header-anchor" href="#_11-3-查看、覆盖与展开" aria-label="Permalink to &quot;11.3 查看、覆盖与展开&quot;">​</a></h3><p>正式语义区分：</p><ol><li><strong>查看内部结构</strong>：显示虚拟展开，仍与预设关联；</li><li><strong>覆盖参数或局部行为</strong>：保持预设身份，只替换公开插槽；</li><li><strong>转为本地结构</strong>：物化内部节点和片段，明确脱离上游更新；</li><li><strong>保存为项目预设</strong>：把本地结构重新封装为可复用资源。</li></ol><p>无论折叠还是展开，最终都必须进入相同编译和正式运行时路径。不能出现“模板模式”和“展开模式”行为不一致。</p><p>“查看内部结构”和“转为本地结构”具有不同的文件语义：</p><ul><li>查看内部结构是只读虚拟视图，由“精确预设版本 + 实例参数 + 插槽覆盖”解析得到；预设内部节点不会复制进当前 Scene，编辑器只允许修改公开参数和插槽；</li><li>虚拟节点使用由实例 ID 与预设内部 ID 派生的稳定调试身份，因此折叠和展开仍能对应同一个运行实例；</li><li>转为本地结构是一个明确、可撤销的文档事务：把当前已解析结构物化到本地，生成当前文档命名空间中的稳定 ID，保留来源和 ID 映射作为 provenance，然后解除上游更新关系；</li><li>转为本地后不会因为预设升级而偷偷重写。重新绑定预设属于另一个需要预览差异的显式操作；</li><li>保存为项目预设则把本地结构重新封装为新的稳定预设 ID，不覆盖原上游包。</li></ul><h3 id="_11-4-预设版本与迁移" tabindex="-1">11.4 预设版本与迁移 <a class="header-anchor" href="#_11-4-预设版本与迁移" aria-label="Permalink to &quot;11.4 预设版本与迁移&quot;">​</a></h3><p>预设实例必须记录稳定预设 ID、精确解析版本、参数覆盖和插槽覆盖。项目依赖锁定到精确版本；即使是内置预设，也不因编辑器升级而静默改变已有弹幕。</p><p>升级流程固定为：</p><ol><li>编辑器发现可用新版本并读取该预设声明的迁移链；</li><li>在临时副本上迁移公开参数 ID、类型和插槽，不依赖容易变化的内部节点位置；</li><li>显示结构差异、参数差异、诊断和正式预览对比；</li><li>作者确认后，以一个 Undo/Redo 事务更新实例与项目依赖锁；</li><li>迁移失败时继续保留旧版本，不能半升级或静默丢弃覆盖。</li></ol><p>插件或预设包应能被项目 vendoring，以保证旧项目可重放。精确版本缺失时，文档以带诊断的降级模式打开并保留原数据，不自动转为本地结构，也不拿“最接近的新版本”猜测替代。</p><h3 id="_11-5-首发最小预设库与新手测试" tabindex="-1">11.5 首发最小预设库与新手测试 <a class="header-anchor" href="#_11-5-首发最小预设库与新手测试" aria-label="Permalink to &quot;11.5 首发最小预设库与新手测试&quot;">​</a></h3><p>首发库不追求堆数量，而覆盖一条可以学习的组合路径：</p><ul><li>Pattern：自机狙、奇偶数扇形、圆形开花、扇形扫射、单双螺旋、延迟转向、子弹分裂；</li><li>Wave：单编队入场、左右交替、编队自机狙、精英/中 Boss；</li><li>Phase：普通攻击、标准符卡、耐久、击破演出；</li><li>Stage 骨架：Pattern 实验、短道中、标准 Boss 战；</li><li>Background：滚动道中背景、符卡背景转场。</li></ul><p>每个预设必须可直接运行、参数少而有意义、可以查看内部结构，并至少教会一个新概念。高级效果可以作为后续包增加，但不能挤占首次选择界面。</p><p>每轮可用性验证至少邀请 5 名没有 PySTG 经验的目标用户，不由维护者口头带做。首轮门槛建议为：至少 4 人能在 10 分钟内从模板得到并修改一个正式预览 Pattern；在 30 分钟内完成一个带“上一波全灭后继续”的短道中；在 60 分钟内完成两阶段 Boss、一次背景转场和一次事件反应，全程不写脚本。还要观察他们能否找到搜索入口、理解状态图与时间线边界、通过 Undo 恢复误操作，并从调参数自然进入一次局部展开。</p><p>测试记录完成时间、求助次数、无效点击、撤销次数、首次脚本冲动、诊断理解和正式预览性能。任何任务需要讲解“内部对象 ID”“运行时池”或插件注册，说明顶层流程仍然泄漏了引擎概念。</p><h2 id="_12-快速搜索与创建入口" tabindex="-1">12. 快速搜索与创建入口 <a class="header-anchor" href="#_12-快速搜索与创建入口" aria-label="Permalink to &quot;12. 快速搜索与创建入口&quot;">​</a></h2><p>编辑器的主要创建入口应是上下文感知搜索，而不是巨大菜单。</p><p>在任意作者上下文轻按空格，可以搜索：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>开花</span></span>
<span class="line"><span>  圆形开花</span></span>
<span class="line"><span>  多层开花</span></span>
<span class="line"><span>  延迟开花</span></span>
<span class="line"><span>  自定义开花生成器</span></span>
<span class="line"><span></span></span>
<span class="line"><span>等待</span></span>
<span class="line"><span>  等待时间</span></span>
<span class="line"><span>  等待移动结束</span></span>
<span class="line"><span>  等待血量条件</span></span>
<span class="line"><span>  等待事件</span></span></code></pre></div><p>搜索结果由统一的 Action Catalog 提供，每个条目声明：</p><ul><li>可出现的上下文；</li><li>输入和输出类型；</li><li>所需能力；</li><li>创建或修改命令；</li><li>中文名、别名、拼音和标签；</li><li>来源：内置、项目或插件；</li><li>帮助和性能提示。</li></ul><p>上下文过滤示例：</p><ul><li>从 <code>PointSet</code> 端口拉线时，只显示接受点集的行为；</li><li>在时间线中，只显示轨道、片段和编排动作；</li><li>在场景画布中，只显示当前父节点允许创建的对象；</li><li>在 Inspector 中，显示绑定、转曲线、重置和暴露为参数等操作。</li></ul><p>所有搜索动作都必须生成正式 Command，并进入对应文档的 Undo/Redo 栈。</p><p>空格与画布平移的交互可以采用“轻按打开搜索、按住拖动平移”，或提供可配置替代快捷键；最终行为需要通过原生交互 QA 冻结。</p><h2 id="_13-短期非目标-自然语言和-agentic-生成" tabindex="-1">13. 短期非目标：自然语言和 Agentic 生成 <a class="header-anchor" href="#_13-短期非目标-自然语言和-agentic-生成" aria-label="Permalink to &quot;13. 短期非目标：自然语言和 Agentic 生成&quot;">​</a></h2><p>短期与中期产品规划不考虑用自然语言或 Agentic Coding 生成弹幕、时间线或行为图，也不把模型服务作为编辑器依赖。</p><p>弹幕创作依赖精确帧数、角度、速度、数量、随机种子、生命周期和性能预算。自然语言容易隐藏默认值与歧义，生成后的大块结构还会增加审查成本，弱化“作者知道当前资源为何这样运行”的可调试性。</p><p>本阶段只保留确定性的上下文搜索：中文名、别名、拼音、标签、输入输出类型和当前位置共同筛选 Action、Preset、Track 与资源。搜索负责快速找到结构，Inspector、曲线、时间线和行为图负责精确编辑。</p><p>未来若重新评估自然语言，也必须建立在结构化 authoring 模型已经稳定、确有用户证据且生成结果能逐字段确认的前提上；这不是当前愿景对应路线图的承诺。</p><h2 id="_14-行为扩展协议" tabindex="-1">14. 行为扩展协议 <a class="header-anchor" href="#_14-行为扩展协议" aria-label="Permalink to &quot;14. 行为扩展协议&quot;">​</a></h2><p>未来需要一个统一的 Behavior Descriptor 概念，把运行时行为和编辑器工具连接起来。概念上至少描述：</p><ul><li>稳定 ID 和版本；</li><li>输入、输出和端口类型；</li><li>参数 schema、单位和可绑定性；</li><li>所需能力；</li><li>执行类型：数据内核、稀疏控制器、Renderer Pass 等；</li><li>生命周期和取消语义；</li><li>编译器；</li><li>调试快照 schema；</li><li>可选编辑器贡献。</li></ul><p>具体类名、字段和注册方式尚未冻结。</p><h3 id="_14-1-complexmapemitter-示例" tabindex="-1">14.1 ComplexMapEmitter 示例 <a class="header-anchor" href="#_14-1-complexmapemitter-示例" aria-label="Permalink to &quot;14.1 ComplexMapEmitter 示例&quot;">​</a></h3><p>高级开发者提供一个复映射发射器插件：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ComplexMapEmitter</span></span>
<span class="line"><span>输入：采样域、函数参数、采样数、颜色映射、触发与取消</span></span>
<span class="line"><span>输出：started、progress、completed、generated_count</span></span>
<span class="line"><span>Runtime：批量计算或合适的数据内核</span></span>
<span class="line"><span>Tool：采样区域控制柄、Inspector、预览叠层、搜索项、预设</span></span>
<span class="line"><span>Debug：状态、生成进度、CPU/GPU 耗时、当前函数参数</span></span></code></pre></div><p>普通作者看到：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>函数：z² + c</span></span>
<span class="line"><span>采样域：圆盘</span></span>
<span class="line"><span>采样数：256</span></span>
<span class="line"><span>映射方式：位置映射</span></span>
<span class="line"><span>颜色：arg(z)</span></span></code></pre></div><p>高级作者可以进入源码，但两者操作的是同一个行为实例和同一套生命周期、类型与调试协议。</p><h3 id="_14-2-runtime、tool-与-schema-的插件包装" tabindex="-1">14.2 Runtime、Tool 与 schema 的插件包装 <a class="header-anchor" href="#_14-2-runtime、tool-与-schema-的插件包装" aria-label="Permalink to &quot;14.2 Runtime、Tool 与 schema 的插件包装&quot;">​</a></h3><p>一个扩展功能使用一个可安装、可锁定版本的插件包，避免作者分别寻找“运行插件”“编辑器插件”和“schema 插件”并自行匹配版本。包内贡献按职责分区：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Plugin Package</span></span>
<span class="line"><span>├─ manifest + dependency/version constraints</span></span>
<span class="line"><span>├─ schema + migrations</span></span>
<span class="line"><span>├─ runtime/compiler contributions</span></span>
<span class="line"><span>├─ editor/tool contributions（可选）</span></span>
<span class="line"><span>└─ assets/examples/presets（可选）</span></span></code></pre></div><p>“一个包”不等于“一个拥有全部权限的模块”：</p><ul><li>headless 游戏运行只加载 schema、compiler 和 Runtime 部分，绝不能因此导入 Qt；</li><li>编辑器按需加载 Inspector、控制柄、轨道、搜索项和调试视图；</li><li>schema 与 migration 是纯数据/纯转换层，不依赖 Renderer 或编辑器实例；</li><li>Runtime 与 Tool 分别获得不同的注册上下文和能力声明，不能从 Tool 贡献取得 Engine 内部对象；</li><li>各分区激活均为事务式，失败时回滚自己的贡献，卸载时按所有权清理；</li><li>缺少 Tool 部分时可以退化为通用 Inspector；缺少必需 Runtime/Compiler 时必须产生可定位的编译错误，不能假装预览成功。</li></ul><p>资源记录插件 ID、资源类型和兼容版本范围；项目依赖锁记录实际解析版本。这样 ComplexMapEmitter 的运行算法、参数 schema、迁移、控制柄和调试器可以一起发布，同时继续保持运行时与编辑器进程边界。</p><h2 id="_15-脚本的使用边界" tabindex="-1">15. 脚本的使用边界 <a class="header-anchor" href="#_15-脚本的使用边界" aria-label="Permalink to &quot;15. 脚本的使用边界&quot;">​</a></h2><p>顶层作者完成第一整关时，原则上不应写脚本。</p><p>以下需求不应要求脚本：</p><ul><li>等待敌人全灭；</li><li>按 HP、时间、难度或事件触发；</li><li>安排敌人波次；</li><li>移动 Boss；</li><li>播放音频；</li><li>调整背景、摄像机、雾和滚动；</li><li>用曲线或变量改变弹量和速度；</li><li>组合已有分裂、转向、旋转和波纹行为。</li></ul><p>脚本适用于：</p><ul><li>新的数学或生成算法；</li><li>有内部记忆的稀疏控制器；</li><li>新行为、新机制或新组件；</li><li>新事件适配器；</li><li>新背景算法、Shader 或 Renderer Pass；</li><li>暂时无法由标准行为协议表达、但边界明确的高级扩展。</li></ul><p>如果作者只是因为图太乱而写脚本，优先检查是否缺少子图、预设、表达式或领域工具；脚本不应成为修复编辑器表达力不足的默认出口。</p><h3 id="_15-1-safe-层不新增通用-dsl" tabindex="-1">15.1 Safe 层不新增通用 DSL <a class="header-anchor" href="#_15-1-safe-层不新增通用-dsl" aria-label="Permalink to &quot;15.1 Safe 层不新增通用 DSL&quot;">​</a></h3><p>Safe 行为由版本化数据动作、状态图、时间线、预设、曲线、只包含 Safe 节点的类型化行为图、类型化变量/事件和受限表达式共同构成。短期不再设计一门能表达任意控制流的通用 Safe DSL，因为它会复制行为图和脚本的类型系统、调试器、迁移与学习成本。</p><p>若作者需要文本输入，文本只能是结构化属性或受限表达式的另一种编辑视图，不能成为第六套运行语义。新的常见需求应优先沉淀成 Action、Preset、Reaction 或领域专用控件；真正的新算法进入 Runtime Behavior。</p><h3 id="_15-2-不提供进程内-safe-python" tabindex="-1">15.2 不提供进程内 Safe Python <a class="header-anchor" href="#_15-2-不提供进程内-safe-python" aria-label="Permalink to &quot;15.2 不提供进程内 Safe Python&quot;">​</a></h3><p>当前和未来默认都把进程内 Python 视为受信任的 Runtime API。限制一个 <code>ctx</code> 对象不能阻止模块导入、文件访问、全局状态或进程级副作用，因此不能称为沙箱。</p><p>短期不交付 Safe Python。若未来出现真实的非受信代码需求，只能采用独立进程、版本化 IPC、能力代理、时间/内存限制和批量命令协议；其热重载默认重建进程与局部状态，不承诺任意 Python 对象迁移。该隔离执行器是独立安全项目，不是顶层内容创作的必经路径。</p><h2 id="_16-背景工作流与钩子" tabindex="-1">16. 背景工作流与钩子 <a class="header-anchor" href="#_16-背景工作流与钩子" aria-label="Permalink to &quot;16. 背景工作流与钩子&quot;">​</a></h2><p>普通作者看到的背景应是可编排资源，而不是裸 renderer callback。</p><h3 id="_16-1-三种常见关系" tabindex="-1">16.1 三种常见关系 <a class="header-anchor" href="#_16-1-三种常见关系" aria-label="Permalink to &quot;16.1 三种常见关系&quot;">​</a></h3><h4 id="时间片段" tabindex="-1">时间片段 <a class="header-anchor" href="#时间片段" aria-label="Permalink to &quot;时间片段&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>0–2 秒：从道中背景过渡到符卡背景</span></span>
<span class="line"><span>2–20 秒：缓慢旋转和推进</span></span>
<span class="line"><span>20–22 秒：恢复并淡出</span></span></code></pre></div><h4 id="连续绑定" tabindex="-1">连续绑定 <a class="header-anchor" href="#连续绑定" aria-label="Permalink to &quot;连续绑定&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fog.density       &lt;- boss.enrage_level</span></span>
<span class="line"><span>camera.rotation   &lt;- phase_progress * 8</span></span>
<span class="line"><span>warp.intensity    &lt;- 1 - boss.hp_ratio</span></span></code></pre></div><h4 id="一次性事件-cue" tabindex="-1">一次性事件 cue <a class="header-anchor" href="#一次性事件-cue" aria-label="Permalink to &quot;一次性事件 cue&quot;">​</a></h4><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>spell.started     -&gt; 播放符卡背景转场</span></span>
<span class="line"><span>spell.ended       -&gt; 恢复默认背景</span></span>
<span class="line"><span>boss.defeated     -&gt; 停止扭曲并淡出</span></span></code></pre></div><h3 id="_16-2-生命周期事件" tabindex="-1">16.2 生命周期事件 <a class="header-anchor" href="#_16-2-生命周期事件" aria-label="Permalink to &quot;16.2 生命周期事件&quot;">​</a></h3><p>可选择的正式事件可以包括：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>stage.enter</span></span>
<span class="line"><span>section.enter</span></span>
<span class="line"><span>section.exit</span></span>
<span class="line"><span>boss.enter</span></span>
<span class="line"><span>spell.declare</span></span>
<span class="line"><span>spell.start</span></span>
<span class="line"><span>spell.end</span></span>
<span class="line"><span>boss.defeated</span></span></code></pre></div><p>作者应在激活面板中选择这些事件，而不是默认编写 <code>on_spell_start()</code>。只有创造新的渲染算法、Shader、程序化几何或 Renderer Pass 时，才进入 Runtime 插件层。</p><h3 id="_16-3-renderer-pass-边界" tabindex="-1">16.3 Renderer Pass 边界 <a class="header-anchor" href="#_16-3-renderer-pass-边界" aria-label="Permalink to &quot;16.3 Renderer Pass 边界&quot;">​</a></h3><p>普通内容只实例化 Pass 预设、绑定输入并动画公开参数。Runtime Renderer Pass 通过后端中立的 <code>PassDescriptor</code> 进入 Render Graph，而不是接收一个可以任意修改全局 GL 状态的裸回调。</p><p>Descriptor 至少声明：</p><ul><li>输入和输出附件；</li><li>格式、尺寸、采样和 load/store 要求；</li><li>执行阶段、依赖、排序和是否允许与其他 Pass 合并；</li><li>参数 schema、可动画字段和默认值；</li><li>临时资源所有权、生命周期和清理；</li><li>支持的后端、所需 capability 和可选显式 fallback；</li><li>CPU/GPU 性能预算和调试标签。</li></ul><p>编译器验证 Render Graph 的依赖环、读写 hazard、格式兼容和能力要求，再由各后端 adapter 生成实际命令。插件只获得受限 Pass Context、Command Encoder 和作用域化资源 lease；不能访问或污染全局 GL 状态，也不能持有超出生命周期的引擎资源。</p><p>不支持目标后端时必须在编译/导出阶段报错。只有插件显式声明且效果语义可接受时，才允许 pass-through 或替代实现，不能静默关闭效果。Tool 贡献可以为同一 Descriptor 增加 Inspector、缩略预览和画布控制柄，但不能另建一条与正式 Render Graph 不同的 Qt 效果实现并宣称 parity。</p><h2 id="_17-事件反应、生命周期、所有权与取消" tabindex="-1">17. 事件反应、生命周期、所有权与取消 <a class="header-anchor" href="#_17-事件反应、生命周期、所有权与取消" aria-label="Permalink to &quot;17. 事件反应、生命周期、所有权与取消&quot;">​</a></h2><p>时间线与行为图的边界固定为：</p><blockquote><p>行为、碰撞和对象生命周期发布已经发生的事实；反应规则描述事实发生后要做什么；时间线决定某条阶段性反应规则在什么时候有效；任务作用域负责反应启动后的等待、循环、子任务和收尾。</p></blockquote><p>因此，时间线上可以放置“等待触发的生命周期内容”，但作者文档保存的是一个处于特定时间窗口的反应定义，而不是等待蓝图直接调用的片段入口。行为图不通过片段 ID 操纵时间线；它发布类型化事实，调度器再匹配当前已武装的声明式反应。</p><h3 id="_17-1-四个核心概念" tabindex="-1">17.1 四个核心概念 <a class="header-anchor" href="#_17-1-四个核心概念" aria-label="Permalink to &quot;17.1 四个核心概念&quot;">​</a></h3><h4 id="lifecycleevent-刚才发生了什么" tabindex="-1">LifecycleEvent：刚才发生了什么 <a class="header-anchor" href="#lifecycleevent-刚才发生了什么" aria-label="Permalink to &quot;LifecycleEvent：刚才发生了什么&quot;">​</a></h4><p><code>LifecycleEvent</code> 是运行时在确定调度边界产生的不可变事实。它至少需要携带事件类型、来源、所有者、正式帧、有效载荷和必要的终止原因。</p><p>例如：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bullet.terminated(reason=expired, position=...)</span></span>
<span class="line"><span>emitter.completed(generated=256)</span></span>
<span class="line"><span>decoy.hit(source=player_bullet, damage=3)</span></span>
<span class="line"><span>enemy.defeated(enemy_tag=midboss_guard)</span></span></code></pre></div><p>事件本身没有动作，也不知道谁会处理它。高密度子弹的生命周期事件在语义上仍是事件，但其运行表示必须允许批量化，不能等同于为每发子弹创建一个 Python <code>Event</code> 对象。</p><h4 id="reactionspec-发生后怎样反应" tabindex="-1">ReactionSpec：发生后怎样反应 <a class="header-anchor" href="#reactionspec-发生后怎样反应" aria-label="Permalink to &quot;ReactionSpec：发生后怎样反应&quot;">​</a></h4><p><code>ReactionSpec</code> 是可序列化、可检查、可调试的声明式规则：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Trigger + Filter + Gate + Policy + Action + Scope</span></span></code></pre></div><ul><li><code>Trigger</code>：监听哪一种事实；</li><li><code>Filter</code>：限定来源、标签、终止原因、攻击来源或其他载荷；</li><li><code>Gate</code>：当前变量、状态或作用域条件是否允许反应；</li><li><code>Policy</code>：逐个、同帧首次、同帧计数、去抖、冷却和并发限制；</li><li><code>Action</code>：启动哪个 Pattern、行为、预设、背景 cue 或变量命令；</li><li><code>Scope</code>：反应归谁所有，何时随父级取消。</li></ul><p>如果一种反应是对象无论在哪里复用都具有的固有能力，例如“这种子弹自然到期时一定开花”，<code>ReactionSpec</code> 应随子弹行为资源或预设保存。如果反应只属于某一符卡、阶段或时间窗口，则由时间线上的 <code>ReactiveClip</code> 持有。如果事件意味着整个关卡阶段发生变化，则由状态图声明转移，而不是把转场偷偷藏在敌人蓝图里。</p><h4 id="reactiveclip-什么时候允许这条规则生效" tabindex="-1">ReactiveClip：什么时候允许这条规则生效 <a class="header-anchor" href="#reactiveclip-什么时候允许这条规则生效" aria-label="Permalink to &quot;ReactiveClip：什么时候允许这条规则生效&quot;">​</a></h4><p><code>ReactiveClip</code> 是时间线上的“武装反应区域”。它不规定事件必然在某个绝对时间发生，而是声明：在这个阶段或时间窗口内，如果指定事件到来且过滤与门控通过，就按给定策略启动动作。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>8.0s  [──────── 假 Boss 受击反击：Armed ────────]  20.0s</span></span>
<span class="line"><span>              监听 decoy.hit</span></span>
<span class="line"><span>              过滤 target=decoy, source=player_bullet</span></span>
<span class="line"><span>              策略 count_per_frame, cooldown=6f</span></span>
<span class="line"><span>              动作 CounterBurst</span></span></code></pre></div><p>它可以覆盖固定区间，也可以覆盖整个父状态，或由另一个事件/条件武装和解除。作者文档始终只保存定义；真正触发时，调度器创建运行时反应实例并在时间线上留下 trace 标记，不把重复实例写回文档。</p><p>这正是“可触发生命周期”的推荐形态，但需要把三件事分开显示：</p><ol><li>片段是否已武装；</li><li>哪个事实真正触发了它；</li><li>启动后的行为实例现在运行到哪里。</li></ol><h4 id="taskscope-启动后谁负责收尾" tabindex="-1">TaskScope：启动后谁负责收尾 <a class="header-anchor" href="#taskscope-启动后谁负责收尾" aria-label="Permalink to &quot;TaskScope：启动后谁负责收尾&quot;">​</a></h4><p><code>TaskScope</code> 管理一次反应启动后的跨帧工作，包括等待、循环、订阅、子行为、临时对象和取消传播。它相当于把 LuaSTG 风格 Task 中有价值的顺序表达保留下来，同时补上明确的所有权和结构化取消。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PhaseScope</span></span>
<span class="line"><span>└─ ClipScope</span></span>
<span class="line"><span>   └─ ReactionScope</span></span>
<span class="line"><span>      └─ BehaviorScope</span></span></code></pre></div><p>立即完成的单帧动作不需要常驻协程；只要稀疏编排动作跨越多个调度边界，就必须进入可追踪的 <code>TaskScope</code>。父级退出后，所有等待和子任务都应被统一取消，不能继续在已结束的符卡之外发弹或切换背景。</p><p><code>TaskScope</code> 不是“每发子弹一个协程”。大量子弹的延迟转向、寿命和分裂倒计时应编译为池内批量状态或批量调度命令，<code>TaskScope</code> 只拥有这一批行为。以 LuaSTG 的常见概念作近似映射：Task 对应稀疏的 <code>TaskBehavior / TaskScope</code>，宏精灵对应可复用的 <code>ActorPreset</code>，宏子弹对应编译到正式弹池的 <code>BulletArchetype</code>；三者共享事件和所有权协议，但运行密度不同。</p><p>四者的最短判断口诀是：</p><table tabindex="0"><thead><tr><th>概念</th><th>回答的问题</th><th>作者通常在哪里看到</th></tr></thead><tbody><tr><td><code>LifecycleEvent</code></td><td>刚才发生了什么？</td><td>事件监视器、对象/行为输出</td></tr><tr><td><code>ReactionSpec</code></td><td>发生后怎样反应？</td><td>预设的反应槽、Inspector、行为资源</td></tr><tr><td><code>ReactiveClip</code></td><td>什么时候这条规则有效？</td><td>阶段时间线</td></tr><tr><td><code>TaskScope</code></td><td>启动后谁负责等待和收尾？</td><td>运行时层级与调试器</td></tr></tbody></table><h3 id="_17-2-具体弹幕与关卡例子" tabindex="-1">17.2 具体弹幕与关卡例子 <a class="header-anchor" href="#_17-2-具体弹幕与关卡例子" aria-label="Permalink to &quot;17.2 具体弹幕与关卡例子&quot;">​</a></h3><h4 id="例一-子弹自然结束后死亡开花" tabindex="-1">例一：子弹自然结束后死亡开花 <a class="header-anchor" href="#例一-子弹自然结束后死亡开花" aria-label="Permalink to &quot;例一：子弹自然结束后死亡开花&quot;">​</a></h4><p>一个“死亡开花弹”预设可以声明：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Trigger: bullet.terminated</span></span>
<span class="line"><span>Filter:  reason == expired</span></span>
<span class="line"><span>Policy:  each</span></span>
<span class="line"><span>Action:  在终止位置生成 12 发小环</span></span>
<span class="line"><span>Scope:   bullet owner / current phase</span></span></code></pre></div><p>如果这种子弹在任何地方自然结束都应该开花，规则随预设保存，作者只调整数量、速度和颜色。如果只有符卡后半段允许开花，子弹仍然只发布 <code>bullet.terminated</code>，时间线后半段的 <code>ReactiveClip</code> 再按 owner tag、子弹类型和终止原因监听它。不要让子弹蓝图查找并启动“后半段开花片段”。</p><p>阶段统一消弹产生的是 <code>phase_cleared</code>，默认不会被“自然结束”过滤器接受，因此不会在符卡结束时意外产生全屏二次开花。</p><h4 id="例二-假-boss-被玩家子弹命中后过量反击" tabindex="-1">例二：假 Boss 被玩家子弹命中后过量反击 <a class="header-anchor" href="#例二-假-boss-被玩家子弹命中后过量反击" aria-label="Permalink to &quot;例二：假 Boss 被玩家子弹命中后过量反击&quot;">​</a></h4><p>碰撞系统或假 Boss 行为发布：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>decoy.hit(target=decoy_1, source=player_bullet, position=..., damage=...)</span></span></code></pre></div><p>假 Boss 所在阶段的时间线上放置一个 <code>ReactiveClip</code>：</p><ul><li>只在假 Boss 可见且可受击的区间武装；</li><li>过滤 <code>target=decoy_1</code> 和 <code>source=player_bullet</code>；</li><li>将同一帧的多次命中聚合为一次或一个计数；</li><li>应用冷却、并发数和每帧生成预算；</li><li>启动 <code>CounterBurst</code> Pattern，并把它放入当前 <code>ReactionScope</code>。</li></ul><p>这样，碰撞与对象行为只负责报告“假 Boss 被打了”，阶段编排负责“这个时期是否反击、反击多凶”。退出该阶段时，尚未完成的延迟反击随 <code>PhaseScope</code> 一起取消。</p><h4 id="例三-击破敌人后切换背景-scene" tabindex="-1">例三：击破敌人后切换背景 Scene <a class="header-anchor" href="#例三-击破敌人后切换背景-scene" aria-label="Permalink to &quot;例三：击破敌人后切换背景 Scene&quot;">​</a></h4><p>这里要先判断它是局部演出，还是阶段语义：</p><ul><li>只是这一小段战斗的视觉 cue：时间线上的 <code>ReactiveClip</code> 监听 <code>enemy.defeated</code> 或 <code>encounter.cleared</code>，在背景轨道启动转场；</li><li>击破意味着进入下一阶段：状态图监听该事件并发生状态转移，新状态自己的时间线负责背景、BGM、Boss 移动和下一轮弹幕；</li><li>敌人蓝图只发布击破事实，不直接调用 <code>set_background_scene()</code>，也不持有背景轨道或片段 ID。</li></ul><p>前者属于阶段内编排，后者属于阶段边界。两种做法都能在顶层视图看到原因和实际触发帧。</p><h4 id="例四-三段延迟开花" tabindex="-1">例四：三段延迟开花 <a class="header-anchor" href="#例四-三段延迟开花" aria-label="Permalink to &quot;例四：三段延迟开花&quot;">​</a></h4><p>一次终止事件触发 <code>ReactionSpec</code> 后，<code>TaskScope</code> 可以表达：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>立即生成第一圈</span></span>
<span class="line"><span>等待 12 帧</span></span>
<span class="line"><span>生成第二圈</span></span>
<span class="line"><span>等待 12 帧</span></span>
<span class="line"><span>生成第三圈</span></span>
<span class="line"><span>完成</span></span></code></pre></div><p>“为什么开始”由事件与反应规则回答，“开始后怎样按顺序运行”由行为和 <code>TaskScope</code> 回答。若符卡在第二次等待期间结束，取消沿所有权链传播，第三圈不会脱离阶段继续生成。</p><h3 id="_17-3-预设怎样承载和展开反应" tabindex="-1">17.3 预设怎样承载和展开反应 <a class="header-anchor" href="#_17-3-预设怎样承载和展开反应" aria-label="Permalink to &quot;17.3 预设怎样承载和展开反应&quot;">​</a></h3><p>预设不应把钩子封死在不可见脚本中，而应暴露类型化的反应槽。例如 <code>DeathBloomBullet</code> 可以向顶层作者提供：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>死亡效果：圆形开花</span></span>
<span class="line"><span>触发原因：自然到期</span></span>
<span class="line"><span>数量：12</span></span>
<span class="line"><span>延迟：0f</span></span>
<span class="line"><span>仅在时间线片段内启用：可选</span></span></code></pre></div><p>顶层作者可以只调这些参数；选择“仅在时间线片段内启用”时，编辑器可在当前时间线创建或绑定一个 <code>ReactiveClip</code>。展开预设后，进阶作者看到的是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BulletArchetype</span></span>
<span class="line"><span>└─ ReactionSlot: on_terminated</span></span>
<span class="line"><span>   ├─ Filter: reason == expired</span></span>
<span class="line"><span>   ├─ Policy: each</span></span>
<span class="line"><span>   └─ Action: BloomPattern</span></span></code></pre></div><p>作者可以局部替换过滤器、策略或动作，而不必把整个预设推倒重写。高级开发者也可以用 Runtime API 提供新的 Action 或可视化反应类型，但它们仍遵守同一事件、作用域和调试协议。</p><h3 id="_17-4-终止原因必须是正式语义" tabindex="-1">17.4 终止原因必须是正式语义 <a class="header-anchor" href="#_17-4-终止原因必须是正式语义" aria-label="Permalink to &quot;17.4 终止原因必须是正式语义&quot;">​</a></h3><p>“死亡”不能只有一个含糊的布尔值。愿景层至少必须区分下列语义；最终枚举名和 payload 由实现时的 schema 契约冻结：</p><table tabindex="0"><thead><tr><th>终止原因</th><th>含义</th><th>默认死亡效果是否应响应</th></tr></thead><tbody><tr><td><code>hit_destroyed</code></td><td>因命中或受击规则被销毁</td><td>由预设明确选择</td></tr><tr><td><code>expired</code></td><td>寿命或自身流程自然结束</td><td>通常响应</td></tr><tr><td><code>out_of_bounds</code></td><td>离开有效世界边界</td><td>通常不响应</td></tr><tr><td><code>bomb_cancelled</code></td><td>被玩家 Bomb 或消弹机制取消</td><td>默认不响应</td></tr><tr><td><code>phase_cleared</code></td><td>阶段结束时统一清场</td><td>默认不响应</td></tr><tr><td><code>owner_cancelled</code></td><td>所有者被取消或销毁</td><td>默认不响应</td></tr><tr><td><code>replaced</code></td><td>因重启、热重载或实例替换而终止</td><td>默认不响应</td></tr></tbody></table><p>反应必须按明确原因过滤。尤其不能让符卡结束、热重载或清屏弹幕触发面向自然死亡设计的二次生成链。</p><h3 id="_17-5-同帧批处理、递归与预算边界" tabindex="-1">17.5 同帧批处理、递归与预算边界 <a class="header-anchor" href="#_17-5-同帧批处理、递归与预算边界" aria-label="Permalink to &quot;17.5 同帧批处理、递归与预算边界&quot;">​</a></h3><p>稀疏的 <code>boss.defeated</code>、<code>wave.completed</code> 等事件可以逐条进入高层事件总线；成百上千发子弹的 <code>bullet.terminated</code> 必须走数据化批处理路径。正式 authoring 路径不得扩大为逐弹 Python callback 或逐弹通用事件对象。</p><p>高密度反应至少需要支持以下策略：</p><ul><li><code>each</code>：逐个响应，仅在明确选择且预算允许时使用；</li><li><code>first_per_frame</code>：同一规则每帧只响应第一次；</li><li><code>count_per_frame</code>：聚合同帧数量，再把计数交给一次动作；</li><li><code>debounce</code>：在给定窗口内合并触发；</li><li><code>cooldown / max_instances</code>：限制频率和并发实例。</li></ul><p>事件 schema 应声明 <code>sparse</code> 或 <code>batch</code> 密度等级。新建稀疏事件反应默认 <code>each</code>；新建批量事件反应默认 <code>count_per_frame</code>。如果 Action 明确需要每个位置，例如每发自然到期子弹各自开花，预设可以选择 <code>each</code>，但它仍编译为批量过滤和批量生成，而不是逐个 Python 调用。假 Boss 受击这类可能同帧多次命中的模板默认使用 <code>count_per_frame</code>；作者需要“只认第一次”时再显式切换为 <code>first_per_frame</code>，Inspector 必须直接显示该选择。</p><p>编译后的过滤与聚合应尽量按 archetype、owner、tag 和 reason 批量执行，结果写入生成命令缓冲，而不是回到 Python 逐发调用。调度器还必须具备：</p><ul><li>最大反应链深度；</li><li>每帧或每作用域生成预算；</li><li>新生成对象不能重新进入当前这一轮死亡收集；</li><li>预算超限、链深超限和事件溢出时产生结构化诊断，不能静默失控；</li><li>调试器能够把批量事实还原为“哪条规则处理了多少个、抑制了多少个”的可读摘要。</li></ul><p>本帧批量事实只写入 Outbox，下一固定帧才进入反应匹配；新生成对象不能重新进入产生它的死亡收集轮次。最大因果深度、每帧生成数、并发实例数和队列容量属于目标运行配置，不作为每份内容文档各自发明的魔法常量。实现阶段必须根据目标硬件基准冻结默认配置，并把它随导出 profile、trace 和诊断记录下来；内容作者可以选择更低的局部预算，但 Safe 内容不能移除引擎硬上限。</p><p>静态可估算的超预算内容在编译或预览时直接报告。动态超限时，编辑器预览暂停 offending scope 并定位到 <code>ReactionSpec</code>；发行运行时按配置确定性抑制该 scope 的超额命令并记录结构化诊断，不能随机丢弃、跨帧摊薄而悄悄改变弹幕节奏，或让整个进程无界增长。</p><h3 id="_17-6-统一所有权规则" tabindex="-1">17.6 统一所有权规则 <a class="header-anchor" href="#_17-6-统一所有权规则" aria-label="Permalink to &quot;17.6 统一所有权规则&quot;">​</a></h3><p>所有行为、时间线片段、反应和状态都应遵循统一规则：</p><ul><li>父状态拥有其时间线实例；</li><li>时间线实例拥有包括 <code>ReactiveClip</code> 在内的片段实例；</li><li><code>ReactiveClip</code> 拥有每次触发形成的 <code>ReactionScope</code>；</li><li>行为拥有自己创建的稀疏对象和弹幕 owner tag；</li><li>父级停止或退出时，取消向下传播；</li><li><code>stop</code> 和 <code>cancel</code> 必须幂等；</li><li>失败不能跳过清理；</li><li>热重载必须明确保留、迁移或重建哪些局部状态；</li><li>停止一个实例不能清理其他实例的资源。</li></ul><p>“等待事件”“等待移动结束”等动作必须绑定取消令牌，不能留下脱离所有者的协程或订阅。</p><h2 id="_18-分层调试器" tabindex="-1">18. 分层调试器 <a class="header-anchor" href="#_18-分层调试器" aria-label="Permalink to &quot;18. 分层调试器&quot;">​</a></h2><p>调试器需要同时服务普通作者和高级开发者。</p><h3 id="_18-1-顶层视图" tabindex="-1">18.1 顶层视图 <a class="header-anchor" href="#_18-1-顶层视图" aria-label="Permalink to &quot;18.1 顶层视图&quot;">​</a></h3><ul><li>当前 Stage / State；</li><li>当前本地时间和正式帧；</li><li>活跃时间线片段；</li><li>已武装和已触发的 <code>ReactiveClip</code>；</li><li>实际触发帧和触发原因；</li><li>主要变量；</li><li>最近事件与批量生命周期事件摘要；</li><li>弹量和性能预算；</li><li>暂停、步进、跳转和重置。</li></ul><h3 id="_18-2-行为实例视图" tabindex="-1">18.2 行为实例视图 <a class="header-anchor" href="#_18-2-行为实例视图" aria-label="Permalink to &quot;18.2 行为实例视图&quot;">​</a></h3><ul><li>作者资源和运行实例 ID；</li><li>生命周期状态；</li><li>输入和输出值；</li><li>所有者与取消令牌；</li><li>已生成数量；</li><li>CPU/GPU 耗时；</li><li>当前子行为；</li><li>错误与能力违规；</li><li>对应的预设内部节点、行为图节点或脚本位置。</li></ul><h3 id="_18-3-事件与变量追踪" tabindex="-1">18.3 事件与变量追踪 <a class="header-anchor" href="#_18-3-事件与变量追踪" aria-label="Permalink to &quot;18.3 事件与变量追踪&quot;">​</a></h3><p>调试器应能回答：</p><ul><li>谁写了这个变量；</li><li>谁读取了它；</li><li>哪个条件在什么值下变为真；</li><li>哪个事件启动或停止了片段；</li><li>哪条 <code>ReactionSpec</code> 接受、聚合或抑制了事件；</li><li>一个 <code>ReactiveClip</code> 是未武装、过滤失败、门控失败、冷却中还是预算受限；</li><li>为什么这个片段没有触发；</li><li>同一属性存在多少个竞争写入者；</li><li>热重载前后保留了哪些状态。</li></ul><h2 id="_19-正式预览原则" tabindex="-1">19. 正式预览原则 <a class="header-anchor" href="#_19-正式预览原则" aria-label="Permalink to &quot;19. 正式预览原则&quot;">​</a></h2><ul><li>所有可宣称运行正确的预览都必须使用正式编译和运行路径；</li><li>Qt 画布可以显示作者几何、控制柄和只读诊断叠层；</li><li>高密度子弹继续留在正式渲染器和数据化运行时；</li><li>结构测试、正式运行时 trace、性能测试和原生视觉验收必须分别记录；</li><li>预设、配方、行为图和脚本最终应汇合到同一正式运行路径；</li><li>Stage/Timeline seek 以重置后确定性重放为正式语义，不通过状态反推伪造目标帧；</li><li>无法正式执行的实验性预览必须明确标记，不得冒充 runtime parity。</li></ul><h2 id="_20-非目标与不可破坏边界" tabindex="-1">20. 非目标与不可破坏边界 <a class="header-anchor" href="#_20-非目标与不可破坏边界" aria-label="Permalink to &quot;20. 非目标与不可破坏边界&quot;">​</a></h2><p>当前愿景不追求：</p><ul><li>把每发子弹变成场景节点；</li><li>给每发子弹安装 Python 每帧回调；</li><li>给每发子弹安装 Python 死亡回调或创建通用 Python 事件对象；</li><li>用一张万能图取代状态图、时间线、UI、背景和弹幕领域编辑器；</li><li>反向解析任意 Python 并承诺无损恢复为可视化图；</li><li>让生成的 Python 成为唯一可运行真源；</li><li>在短期或中期引入自然语言/Agentic 弹幕生成入口；</li><li>用 Qt 近似绘制替代正式 GLFW/ModernGL 运行时；</li><li>在没有测量依据时引入 Redis、远程协作或二进制资源打包；</li><li>在插件 ABI 和安全边界稳定前构建公共插件市场。</li></ul><h2 id="_21-与当前仓库的关系" tabindex="-1">21. 与当前仓库的关系 <a class="header-anchor" href="#_21-与当前仓库的关系" aria-label="Permalink to &quot;21. 与当前仓库的关系&quot;">​</a></h2><p>截至本文首版日期，历史路线图已记录 M0–M7 与 R5–R7 在当时 checkout 的验收闭环；该历史清单现已由下一代实施 TODO 取代。已有基础包括版本化作者资源、正式 Pattern 运行时与预览、可编辑时间线、配方与行为图、表达式与脚本生命周期、UI/背景资源、类型化事件、插件注册和恢复机制。</p><p>v0.3 的决策有意沿现有边界演进：当前 <code>SceneDocument</code> 已拥有稳定 UUID 的 Track/Clip/Keyframe、迁移和 Undo/Redo，因此状态结构扩展它而不另造平行真源；当前 PreviewController 的 <code>seek</code> 已采用 reset 后从 0 固定帧重放，愿景把它确认为长期正式语义。另一方面，当前高层 EventBus 会在一次 <code>dispatch()</code> 中持续排空处理器新加入的事件，尚不具备 v0.3 的逐帧 Inbox/Outbox 隔离；当前 <code>ScriptContext</code> 继承完整 <code>StageContext</code>，也不能被称为 Safe 沙箱。这两点属于未来实施迁移，本文不把愿景写成现有交付声明。</p><p>本文在这些基础上继续讨论的主要是产品层目标形态：</p><ul><li>StageFlow / PhaseFlow 的作者体验；</li><li>条件、事件和变量驱动的片段激活；</li><li>一等预设资源和分层预设库；</li><li>上下文 Action Catalog 与快速搜索；</li><li>Safe / Runtime / Engine 的可执行能力隔离；</li><li>统一 Behavior Descriptor；</li><li>更完整的背景编排和生命周期 cue；</li><li>跨状态、时间线、行为和插件的分层调试器。</li></ul><p>这些条目在进入路线图前一律视为“愿景或待设计”，不能仅凭本文描述为已实现。</p><h2 id="_22-已冻结决策索引" tabindex="-1">22. 已冻结决策索引 <a class="header-anchor" href="#_22-已冻结决策索引" aria-label="Permalink to &quot;22. 已冻结决策索引&quot;">​</a></h2><p>本轮原有待讨论问题已按“便于开发、渐进学习、运行性能、人机交互直觉、编辑器扩展性和充分解耦”收敛：</p><table tabindex="0"><thead><tr><th>原则</th><th>对架构的直接约束</th></tr></thead><tbody><tr><td>便于开发</td><td>一个作者真源、一条编译/预览路径；不平行增加 Flow 文件族、通用 Safe DSL 或第二套渲染器</td></tr><tr><td>新手循序渐进</td><td>可运行骨架和预设先行；参数覆盖、虚拟展开、本地物化、Runtime 扩展逐层开放</td></tr><tr><td>引擎性能</td><td>高密度事实与行为批量化；预算由目标 profile 管理；稀疏 Task 不渗入逐弹路径</td></tr><tr><td>人机交互直觉</td><td>状态图回答阶段、时间线回答顺序、行为图回答局部实现；默认策略可读且运行实例不污染作者文档</td></tr><tr><td>再开发与扩展性</td><td>稳定 ID、版本、迁移、Descriptor、分区插件包和通用降级 Inspector 构成扩展协议</td></tr><tr><td>功能充分解耦</td><td>各域只通过类型化变量、事件、资源引用和生命周期所有权交流，不跨编辑面持有内部对象或片段 ID</td></tr></tbody></table><table tabindex="0"><thead><tr><th>原问题</th><th>结论</th></tr></thead><tbody><tr><td>StageFlow / PhaseFlow 边界</td><td>都是 <code>SceneDocument</code> 内同一种分层 <code>StateGraphSpec</code> 的上下文视图，不新增两类文件</td></tr><tr><td>State 的文件语义</td><td>带稳定 UUID 的内嵌子资源，直接拥有局部时间线；复用通过 <code>PhasePreset</code></td></tr><tr><td>变量作用域和持久化</td><td>Project Config、Stage、State、Clip/Reaction、Behavior、Engine Snapshot 六类；运行值不写回作者文档，默认单写入者</td></tr><tr><td>条件触发默认值</td><td><code>on_rise + once_per_scope + max_instances=1</code>；保持、下降沿、重启和并行均显式选择</td></tr><tr><td>同帧事件和递归</td><td>本帧 Outbox、下一固定帧 Inbox，不允许 dispatch 重入；状态生命周期优先于退出作用域的新反应</td></tr><tr><td>聚合策略和预算</td><td>稀疏事件默认 <code>each</code>，批量事件默认 <code>count_per_frame</code>；硬预算属于经基准冻结的目标运行配置</td></tr><tr><td>动态实例与冲突显示</td><td>作者定义不被运行实例改写；用 trace、堆叠实例和抑制标记显示；新内容的重叠写入必须显式解决</td></tr><tr><td>预设升级</td><td>项目锁定精确版本，迁移在临时副本预览并由作者以一个事务确认，不自动升级</td></tr><tr><td>查看与转为本地</td><td>查看是只读虚拟解析；转本地是物化、记录 provenance、解除上游关系的显式 Undo/Redo 事务</td></tr><tr><td>Safe DSL</td><td>不新增通用 DSL；使用数据动作、状态图、时间线、预设、受限表达式和领域控件</td></tr><tr><td>Safe Python</td><td>短期不提供；进程内 Python 一律属于受信 Runtime，未来如需不可信执行只能独立进程</td></tr><tr><td>插件包装</td><td>一个版本化包共同交付 schema/runtime/tool，但三个分区使用不同能力和加载生命周期</td></tr><tr><td>Renderer Pass</td><td>使用后端中立 Descriptor + Render Graph + backend adapter，不暴露裸全局渲染状态</td></tr><tr><td>自然语言</td><td>短期与中期完全不进入产品规划，只保留确定性的上下文搜索</td></tr><tr><td>任意位置预览</td><td>重置并从作用域入口确定性重放到目标帧，不建设状态反推系统；缓存只可作为等价优化</td></tr><tr><td>新手模板与测试</td><td>采用第 11.5 节的最小组合库；每轮至少 5 名新用户，以无脚本完成 Pattern、道中和两阶段 Boss 为门槛</td></tr></tbody></table><p>最大事件因果深度、每帧生成上限、队列容量和具体性能目标不需要由内容作者或本文凭感觉指定；它们属于实施阶段在目标硬件上测量后冻结的运行 profile。除这些需要性能证据的数值外，本表当前没有遗留的产品方向选择。</p><h2 id="_23-后续修改约定" tabindex="-1">23. 后续修改约定 <a class="header-anchor" href="#_23-后续修改约定" aria-label="Permalink to &quot;23. 后续修改约定&quot;">​</a></h2><p>后续讨论修改本文时：</p><ul><li>已达成共识的内容写入正文；</li><li>尚未决定的内容保留“概念名”“建议”或“待讨论”标记；</li><li>不把愿景描述改写成当前实现声明；</li><li>实施决策需要同步进入路线图并定义验收证据；</li><li>schema/API 变更必须另行形成版本、迁移和 round-trip 契约；</li><li>重大取舍在变更记录中注明原因，不静默覆盖历史方向。</li></ul><h2 id="_24-变更记录" tabindex="-1">24. 变更记录 <a class="header-anchor" href="#_24-变更记录" aria-label="Permalink to &quot;24. 变更记录&quot;">​</a></h2><h3 id="_2026-08-09-—-v0-3-愿景收敛" tabindex="-1">2026-08-09 — v0.3 愿景收敛 <a class="header-anchor" href="#_2026-08-09-—-v0-3-愿景收敛" aria-label="Permalink to &quot;2026-08-09 — v0.3 愿景收敛&quot;">​</a></h3><ul><li>固定 <code>SceneDocument</code> 内嵌分层 <code>StateGraphSpec</code>，StageFlow / PhaseFlow 不成为两套新资源；</li><li>固定 State、变量、条件触发、动态实例、冲突写入和事件下一帧可见语义；</li><li>固定 Stage/Timeline seek 使用重置后确定性重放，不建设任意状态反推系统；</li><li>固定预设精确版本锁、显式迁移、虚拟查看与本地物化的文件语义；</li><li>固定 Safe 层不新增通用 DSL，短期不提供 Safe Python；</li><li>固定插件单包分区、后端中立 Renderer Pass 和目标 profile 性能预算边界；</li><li>将自然语言与 Agentic 生成移出短期、中期规划，只保留上下文搜索；</li><li>固定首发最小预设集合和面向真实新用户的可用性验证门槛；</li><li>将原 16 项待讨论问题全部收敛为正文决策或需基准测量的实施参数。</li></ul><h3 id="_2026-08-09-—-v0-2-事件反应与生命周期模型" tabindex="-1">2026-08-09 — v0.2 事件反应与生命周期模型 <a class="header-anchor" href="#_2026-08-09-—-v0-2-事件反应与生命周期模型" aria-label="Permalink to &quot;2026-08-09 — v0.2 事件反应与生命周期模型&quot;">​</a></h3><ul><li>固定 <code>LifecycleEvent / ReactionSpec / ReactiveClip / TaskScope</code> 四个概念及其职责边界；</li><li>固定“行为发布事实、声明式规则决定反应、时间线决定规则何时有效”的蓝图与时间线交互方式；</li><li>记录死亡开花、假 Boss 受击反击、击破切背景和三段延迟开花的具体归属；</li><li>记录预设通过可展开的反应槽承载钩子，并允许时间线绑定与局部覆盖；</li><li>固定终止原因必须区分自然结束、清场、取消、越界和替换等语义；</li><li>固定高密度生命周期事件走批量路径，不扩展为逐弹 Python 回调；</li><li>保留同帧可见边界、聚合默认值和具体预算为后续确定性契约。</li></ul><h3 id="_2026-08-09-—-v0-1-初稿" tabindex="-1">2026-08-09 — v0.1 初稿 <a class="header-anchor" href="#_2026-08-09-—-v0-1-初稿" aria-label="Permalink to &quot;2026-08-09 — v0.1 初稿&quot;">​</a></h3><ul><li>固定“关卡大纲 → 状态 → 时间线 → 预设/配方 → 行为图 → 脚本”的渐进式创作路径；</li><li>固定状态图、时间线和行为图通过变量、事件、激活/停止规则交互，不直接形成万能跨域蓝图；</li><li>记录内容/行为/工具职责轴和 Safe/Runtime/Engine 信任轴；</li><li>记录新人道中、关底、预览与脚本升级流程；</li><li>记录分层预设、上下文搜索和自然语言结构化编辑方向；</li><li>记录背景编排、Behavior Descriptor、生命周期、取消和分层调试器方向；</li><li>汇总当前仍需讨论的关键问题。</li></ul>`,371)])])}const b=e(n,[["render",s]]);export{u as __pageData,b as default};
